layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: none }
[data-ryt="footer"] { color: var(--ryt-muted); border-top: 1px solid rgb(128, 128, 128); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-top: 2px solid var(--ryt-border); border-right: 2px solid var(--ryt-text); border-bottom: 2px solid var(--ryt-text); border-left: 2px solid var(--ryt-border); border-radius: 0px; box-shadow: color-mix(in srgb, var(--ryt-text) 10%, transparent) 0px 1px 2px 0px; transition: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.1s }
[data-ryt="hero"] h1 { color: var(--ryt-accent); font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: background 0.2s }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-left: 6px solid var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: none; border-top: none; border-right: none; border-bottom: none }
[data-ryt="brand"] { color: var(--ryt-border); background-color: var(--ryt-accent); border-right: 1px solid rgb(128, 128, 128); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-text) 0px 1px 2px, var(--ryt-border) 0px 0px 2px; transition: none; border-top: none; border-bottom: none; border-left: none }
[data-ryt="nav"] a { color: var(--ryt-text); background-color: var(--ryt-surface); border-right: 1px solid rgb(128, 128, 128); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: none; border-top: none; border-bottom: none; border-left: none }
[data-ryt="button"] { color: var(--ryt-text); background-color: var(--ryt-surface); border-right: 1px solid rgb(128, 128, 128); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: none; border-top: none; border-bottom: none; border-left: none }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-border); background-color: rgb(204, 0, 0); border-top: 2px solid rgb(153, 0, 0); border-right: 2px solid rgb(153, 0, 0); border-bottom: 2px solid rgb(153, 0, 0); border-left: 2px solid rgb(153, 0, 0); border-radius: 0px; box-shadow: var(--ryt-border) 1px 1px 0px 0px inset, rgb(153, 0, 0) -1px -1px 0px 0px inset, rgb(230, 0, 0) 1px 1px 0px 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 2px; padding-right: 10px; padding-bottom: 2px; padding-left: 10px; transition: background-color 0.15s, color 0.15s, box-shadow 0.15s, transform 0.15s, filter 0.15s; position: relative }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: none }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: none }
[data-ryt="cover"] { border-radius: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.1s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 700; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: none }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #000080; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="category"]::after, [data-ryt="tags"] li::after { content: ""; display: block; position: absolute; width: 100%; height: 10px; color: var(--ryt-border); background-image: linear-gradient(color-mix(in srgb, var(--ryt-border) 15%, transparent), rgba(255, 255, 255, 0)); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: none; -webkit-text-fill-color: var(--ryt-border); top: 0px; left: 0px }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; transform: translateY(-1px) scale(1.05); box-shadow: 0 0 0 2px color-mix(in srgb, var(--ryt-border) 20%, transparent),inset 0 0 10px color-mix(in srgb, var(--ryt-text) 80%, transparent),0 0 5px color-mix(in srgb, var(--ryt-border) 10%, transparent); filter: brightness(1.1); box-shadow: inset 2px 2px 0 #ffffff,inset -2px -2px 0 #990000,2px 2px 0 #e60000; filter: brightness(1.08) }
[data-ryt="button"]:hover { color: #000080 }
[data-ryt="nav"] a:hover { color: #000080; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #000080 }
[data-ryt="brand"]:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="hero"] h1:hover { color: #000000 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #000080; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
